import{_ as a,o as c,a as t,b as d}from"./app.CIoiBgkh.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"基础定义","link":"/api/SIMD-API/c_api/defs/defs"},{"text":"宏","link":"/api/SIMD-API/c_api/defs/macro/macro"},{"text":"ASC_IS_AIC/ASC_IS_AIV","link":"/api/SIMD-API/c_api/defs/macro/asc_is_aic-asc_is_aiv"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/defs/macro/asc_is_aic-asc_is_aiv.md","filePath":"api/SIMD-API/c_api/defs/macro/asc_is_aic-asc_is_aiv.md","outlineHeaders":[{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"宏定义","slug":"宏定义","link":"#宏定义"},{"level":2,"title":"取值说明","slug":"取值说明","link":"#取值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"}],"lastUpdated":1789526249000}'),i={name:"api/SIMD-API/c_api/defs/macro/asc_is_aic-asc_is_aiv.md"};function _(s,e,o,I,r,A){return c(),t("div",null,[...e[0]||(e[0]=[d(`<div><article class="markdown-body"><h1>ASC_IS_AIC/ASC_IS_AIV</h1><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;c_api/defs/macro.h&quot;</code>。</p><p><code>ASC_IS_AIC</code>和<code>ASC_IS_AIV</code>用于<a href="../../../../../guide/programming_guide/advanced_programming/hardware_implementation/basic_architecture.html">分离模式</a>中对Cube Core（AIC）和Vector Core（AIV）的代码路径进行条件编译和运行，可作为<code>if</code>语句的条件。编译或者运行AIC代码路径时，<code>ASC_IS_AIC</code>条件成立；编译或者运行AIV代码路径时，<code>ASC_IS_AIV</code>条件成立。</p><p>这两个宏分别是<code>ASCEND_IS_AIC</code>和<code>ASCEND_IS_AIV</code>的C API别名，对应宏的功能相同。基于AIC和AIV分离模式开发<code>__mix__</code>融合算子时，可通过这两个宏隔离仅由AIC执行的矩阵计算、矩阵搬运等代码，以及仅由AIV执行的矢量计算、矢量数据搬运等代码。</p><h2 id="宏定义">宏定义<a class="header-anchor" href="#宏定义">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#define ASC_IS_AIC ASCEND_IS_AIC</span>
<span class="cp">#define ASC_IS_AIV ASCEND_IS_AIV</span>
</code></pre></div><h2 id="取值说明">取值说明<a class="header-anchor" href="#取值说明">​</a></h2><table><thead><tr><th>当前代码路径</th><th><code>ASC_IS_AIC</code>条件结果</th><th><code>ASC_IS_AIV</code>条件结果</th></tr></thead><tbody><tr><td>AIC</td><td><code>true</code></td><td><code>false</code></td></tr><tr><td>AIV</td><td><code>false</code></td><td><code>true</code></td></tr></tbody></table><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>这两个宏仅适用<a href="../../../../../guide/programming_guide/advanced_programming/hardware_implementation/basic_architecture.html">分离模式</a>。</li><li>在AIC和AIV分离模式的融合算子中，AIC和AIV执行不同类型的指令。仅支持在AIC上执行的代码必须置于<code>ASC_IS_AIC</code>条件分支内；仅支持在AIV上执行的代码必须置于<code>ASC_IS_AIV</code>条件分支内。</li></ul></article></div>`,1)])])}const n=a(i,[["render",_]]);export{h as __pageData,n as default};
